#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    unordered_set<string> prefixes, suffixes, substrings;
    prefixes.reserve(N * 10);
    suffixes.reserve(N * 10);
    substrings.reserve(N * 50);

    for (int i = 0; i < N; ++i) {
        string s;
        cin >> s;
        int len = static_cast<int>(s.size());

        bool invalid = substrings.count(s);

        for (int split = 1; !invalid && split < len; ++split) {
            string left = s.substr(0, split);
            string right = s.substr(split);
            if (suffixes.count(left) && prefixes.count(right)) {
                invalid = true;
            }
        }

        if (invalid) {
            cout << s << '\n';
            return 0;
        }

        for (int l = 0; l < len; ++l) {
            prefixes.insert(s.substr(0, l + 1));
            suffixes.insert(s.substr(len - l - 1, l + 1));
            for (int r = l; r < len; ++r) {
                substrings.insert(s.substr(l, r - l + 1));
            }
        }
    }

    cout << "ok\n";
    return 0;
}
